'use client';
import { useState } from 'react';
import { ArrowRight, Bell, Check, CurrencyCircleDollar, FileText, Gear, House, Info, Plus, Trash } from '@phosphor-icons/react';
import * as DS from '@/index';

export function ConversationExample(){const [value,setValue]=useState('');const [messages,setMessages]=useState<string[]>([]);return <div className="grid gap-6 w-full"><DS.Conversation><DS.ConversationResponse agent="beni" badge={<DS.Badge>Ejemplo</DS.Badge>}>Esta respuesta es contenido local de muestra.</DS.ConversationResponse>{messages.map((m,i)=><DS.ConversationMessage key={i}>{m}</DS.ConversationMessage>)}</DS.Conversation><DS.ConversationComposer value={value} onValueChange={setValue} onSend={text=>{setMessages([...messages,text]);setValue('');}} disclaimer="Demostración local, sin servicio de IA."/></div>;}

'use client';
import { useState } from 'react';
import { ArrowRight, Bell, Check, CurrencyCircleDollar, FileText, Gear, House, Info, Plus, Trash } from '@phosphor-icons/react';
import * as DS from '@/index';

export function CharactersExample(){const [frame,setFrame]=useState<1|2|3|4|5|6>(1);return <div className="grid gap-4"><div className="flex gap-8"><DS.Characters character="beni" frame={frame} label="BENI"/><DS.Characters character="navi" frame={frame} label="NAVI"/></div><DS.Button variant="text" size="small" onClick={()=>setFrame(frame===6?1:(frame+1) as 2|3|4|5|6)}>Siguiente fotograma</DS.Button></div>;}

'use client';
import { useState } from 'react';
import { ArrowRight, Bell, Check, CurrencyCircleDollar, FileText, Gear, House, Info, Plus, Trash } from '@phosphor-icons/react';
import * as DS from '@/index';

export function ChatSectionExample(){const [value,setValue]=useState('');const [messages,setMessages]=useState<string[]>([]);return <DS.ChatSection state={messages.length?'active':'standby'} userName="Miguel" subtitle="Explora una conversación local" messages={messages.map((m,i)=><DS.ConversationMessage key={i}>{m}</DS.ConversationMessage>)} suggestions={<DS.ChatSuggestion onClick={()=>setValue('Ver documentos')}>Ver documentos</DS.ChatSuggestion>} composer={<DS.ConversationComposer value={value} onValueChange={setValue} onSend={text=>{setMessages([...messages,text]);setValue('');}} disclaimer="Solo datos locales de ejemplo."/>}/>;}
